{"sql": "SET sqlite_all_varchar=true;
WITH abakan_airports AS (
  SELECT airport_code, city, 
         REPLACE(REPLACE(coordinates, '(', ''), ')', '') as coord_clean,
         SUBSTR(REPLACE(REPLACE(coordinates, '(', ''), ')', ''), 1, INSTR(REPLACE(REPLACE(coordinates, '(', ''), ')', ''), ',') - 1) as longitude,
         SUBSTR(REPLACE(REPLACE(coordinates, '(', ''), ')', ''), INSTR(REPLACE(REPLACE(coordinates, '(', ''), ')', ''), ',') + 1) as latitude
  FROM airports_data
  WHERE city LIKE '%Abakan%'
)
SELECT typeof(longitude), typeof(latitude), longitude, latitude FROM abakan_airports", "preview_rows": 5}

